"""All registered interventions on source-reset native last decoder + MLP."""
import argparse,time,torch
from common61 import *
import intervene61 as m
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--plan',required=True);ap.add_argument('--engineering',action='store_true');a=ap.parse_args();p=read(a.plan);pin(p);torch.set_num_threads(4);torch.set_grad_enabled(False);torch.backends.cuda.matmul.allow_tf32=False;torch.backends.cudnn.allow_tf32=False;torch.backends.cudnn.benchmark=False;torch.backends.cudnn.deterministic=True
 rows=read(ROOT/p['manifest']);rows=engineer(rows) if a.engineering else rows;cap=ROOT/('research/round61/engineering_capture_attempt001' if a.engineering else p['capture_root']);ss=read(cap/'SEALED.json');par=load(cap/'DECODER_AND_MLP_PARAMETERS_PRIVATE.npz');dec,head=m.modules(par,'cuda');fingerprint=m.source_fingerprint(dec,head);out=ROOT/('research/round61/engineering_replay_attempt001' if a.engineering else p['prediction_root']);assert not out.exists();out.mkdir(parents=True)
 for f in ['samples_PRIVATE','cases_PRIVATE','selectors_PRIVATE']:(out/f).mkdir()
 start=time.perf_counter();stats=[];status=[];max_h=0.;maxscore=0.
 try:
  for i,row in enumerate(rows):
   sid=row['id'];rel='samples_PRIVATE/'+sid+'.npz';assert sha(cap/rel)==ss['files'][rel];z=load(cap/rel);groot=ROOT/p['association_root'];assert sha(groot/rel)==read(groot/'SEALED.json')['files'][rel];g=load(groot/rel);oldroot=ROOT/p['r59_prediction_root'];assert sha(oldroot/rel)==read(oldroot/'SEALED.json')['files'][rel];old=load(oldroot/rel);r60root=ROOT/p['r60_prediction_root'];assert sha(r60root/rel)==read(r60root/'SEALED.json')['files'][rel];old60=load(r60root/rel)
   result={arm:old['scores'][list(old['arm_names']).index('direct_all' if arm=='r59_direct_all' else arm)] for arm in REFERENCES if not arm.startswith('r60_')}
   for arm,key in [('r60_noise','noise_dynamic'),('r60_common','common_dynamic')]:result[arm]=old60['scores'][list(old60['arm_names']).index(key)]
   hs={v:m.decoder_forward(dec,z,v) for v in 'ABC'};err=max(float((hs[v][0]-torch.tensor(z[v+'_h'],device='cuda')).abs().max()) for v in 'ABC');assert err<=p['engineering_hidden_abs_tolerance'];max_h=max(max_h,err);raw={v:head(hs[v]) for v in 'ABC'};result['zero_replay']=m.compose(raw,z,g);err=float(abs(result['zero_replay']-result['frozen_ABC']).max());assert err<=p['engineering_probability_abs_tolerance'] and result['zero_replay'].argmax()==result['frozen_ABC'].argmax();maxscore=max(maxscore,err)
   detroot=ROOT/p['r60_detection_root'];assert sha(detroot/rel)==read(detroot/'SEALED.json')['files'][rel];det=load(detroot/rel);patchrel='patches_PRIVATE/'+sid+'.npz';assert sha(r60root/patchrel)==read(r60root/'SEALED.json')['files'][patchrel];patch=load(r60root/patchrel);selectors=m.selector_indices(z,head,det,patch);np.savez_compressed(out/'selectors_PRIVATE'/(sid+'.npz'),**{k+'_indices':v[1] for k,v in selectors.items()});details={}
   for arm in HEAD_ARMS+DECODER_ARMS+HEAD_OFF_ARMS:result[arm],details[arm]=m.run_intervention(dec,head,z,g,arm,selectors);assert m.source_fingerprint(dec,head)==fingerprint
   scores=np.stack([result[k] for k in ARMS]);q=scores.argmax(1);assert np.isfinite(scores).all();assert np.array_equal(z['source_boxes'],old['source_boxes']);np.savez_compressed(out/rel,arm_names=np.array(ARMS),scores=scores,queries=q,source_boxes=old['source_boxes'],source_scores=old['source_scores'],selected_original_boxes=old['source_boxes'][q]);dump(out/'cases_PRIVATE'/(sid+'.json'),{'source_hidden_max_error':err,'no_GT_or_fitting':True,'source_restored_exact':True,'interventions':details});stats.append(details);status.append({'id':sid,'arm_statuses':{arm:{'unknown':False,'fallback':False,'no_parameter_update':not details.get(arm,{}).get('actual_parameter_assignment',False)} for arm in ARMS}})
   if (i+1)%16==0:print('R61_CONTROLLED_INTERVENTIONS',i+1,len(rows),flush=True)
  cost={'n':len(rows),'arms':len(ARMS),'native_decoder_forward_calls':len(rows)*3*(1+len(DECODER_ARMS)+len(HEAD_OFF_ARMS)),'actual_controlled_head_forward_calls':len(rows)*3*(1+len(HEAD_ARMS)+len(DECODER_ARMS)+len(HEAD_OFF_ARMS)),'new_full_source_forwards':0,'new_gradient_steps':0,'new_pseudo_label_fits':0,'source_restored_exact':True,'source_prefix_hidden_max_error':max_h,'source_ABC_readout_max_error':maxscore,'seconds':time.perf_counter()-start,'peak_GPU_bytes':int(torch.cuda.max_memory_allocated())};dump(out/'COSTS.json',cost);dump(out/'READOUT_STATUS_PRIVATE.json',status)
  if a.engineering:dump(out/'RESULT.json',{'state':'PASS_R61_REAL_CACHE_NATIVE_LAST_DECODER_AND_HEAD_CONTROLLED_INTERVENTIONS','n':len(rows),'cost':cost})
  seal(out,'R61_CONTROLLED_INTERVENTIONS_SEALED_NO_GT',n=len(rows),arm_names=ARMS,plan_sha256=sha(a.plan));print(cost,flush=True)
 except BaseException as error:dump(out/'FAILED.json',{'type':type(error).__name__,'error':str(error),'completed':len(stats),'automatic_retry':False});raise
if __name__=='__main__':main()
